def run(document, schema, options \\ []) do
  pipeline =
    schema
    |> Absinthe.Pipeline.for_document(options)
    |> case Keyword.get(options, :pipeline_modifier) do
      nil -> &Function.identity/1
      modifier when is_function(modifier, 1) -> modifier
    end.()

  case Absinthe.Pipeline.run(document, pipeline) do
    {:ok, %{result: result}, _blueprint} ->
      {:ok, result}

    {:error, msg, _blueprint} when is_binary(msg) ->
      {:error, msg}

    {:error, errors, _blueprint} ->
      {:ok, %{errors: errors}}

    {:ok, blueprint} ->
      {:ok, blueprint.result}

    {:error, msg} when is_binary(msg) ->
      {:error, msg}

    {:error, errors} ->
      {:ok, %{errors: errors}}
  end
end

